    private fun glyph(name: String, fillType: PathFillType, data: String): ImageVector = ImageVector.Builder(
        name = name,
        defaultWidth = 30.dp,
        defaultHeight = 30.dp,
        viewportWidth = 30f,
        viewportHeight = 30f,
        autoMirror = true,
    ).addPath(addPathNodes(data), fill = SolidColor(Color.Black), pathFillType = fillType).build()
